import React,{createContext,useContext,useEffect,useMemo,useState} from 'react';import{createRoot}from'react-dom/client';import{BrowserRouter,useNavigate,useLocation,useParams,Link,Routes,Route}from'react-router-dom';import{CalendarDays,Compass,LayoutDashboard,ClipboardList,Users,CheckCheck,Bell,Settings,LogOut,Plus,Search,Filter,Clock,MapPin,ChevronRight,CheckCircle2,XCircle,Menu,RefreshCw,ChartNoAxesCombined,Tags,Building2,FileText,UserCircle,ShieldCheck}from'lucide-react';import{api}from'./api';import'./style.css';
const Auth=createContext(null);const useAuth=()=>useContext(Auth);function AuthProvider({children}){const[user,setUser]=useState(null),[loading,setLoading]=useState(true);useEffect(()=>{const t=sessionStorage.getItem('unievents_token');if(t)api.get('/auth/me').then(x=>setUser(x.user)).catch(()=>{sessionStorage.removeItem('unievents_token');sessionStorage.removeItem('unievents_role')}).finally(()=>setLoading(false));else setLoading(false)},[]);const login=async(email,password)=>{sessionStorage.removeItem('unievents_role');const x=await api.post('/auth/login',{email,password});sessionStorage.setItem('unievents_token',x.token);setUser(x.user);return x.user};const switchRole=async role=>{sessionStorage.setItem('unievents_role',role);const x=await api.get('/auth/me');setUser(x.user)};const logout=()=>{sessionStorage.removeItem('unievents_token');sessionStorage.removeItem('unievents_role');setUser(null)};return <Auth.Provider value={{user,setUser,login,logout,switchRole,loading}}>{children}</Auth.Provider>}
const roles={student:'Student',faculty:'Faculty',club:'Club Organizer',admin:'Administrator'};const initials=n=>(n||'U').split(' ').map(x=>x[0]).slice(0,2).join('').toUpperCase();const date=d=>d?new Date(d).toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'}):'—';const datetime=d=>d?new Date(d).toLocaleString('en-IN',{day:'numeric',month:'short',hour:'numeric',minute:'2-digit'}):'—';
function App(){const{user,loading}=useAuth();if(loading)return <div className="loading">Loading UniEvents…</div>;return user?<Shell/>:<Routes><Route path="/register" element={<Register/>}/><Route path="/forgot" element={<Forgot/>}/><Route path="/reset" element={<Reset/>}/><Route path="*" element={<SignIn/>}/></Routes>}
function SignIn(){const{login}=useAuth(),[email,setEmail]=useState('student@bbdu.ac.in'),[password,setPassword]=useState('UniEvents@123'),[error,setError]=useState(''),[busy,setBusy]=useState(false);const go=async e=>{e.preventDefault();setError('');setBusy(true);try{await login(email,password)}catch(x){setError(x.message)}finally{setBusy(false)}};return <div className="auth-page"><div className="auth-art"><div className="brand large"><span className="brand-mark">U</span> UniEvents</div><div className="art-copy"><span className="eyebrow">A MORE CONNECTED CAMPUS</span><h1>Every event.<br/>One university.</h1><p>Discover meaningful experiences and make campus life unforgettable.</p></div><div className="art-foot">Babu Banarasi Das University · Lucknow</div></div><div className="auth-side"><form className="auth-card" onSubmit={go}><span className="eyebrow">WELCOME TO UNIEVENTS</span><h2>Sign in to your account</h2><p className="muted">Use your university credentials to continue.</p>{error&&<div className="alert error">{error}</div>}<label>University email<input type="email" value={email} onChange={e=>setEmail(e.target.value)} required/></label><label>Password<input type="password" value={password} onChange={e=>setPassword(e.target.value)} required/></label><div className="row-between"><Link to="/forgot" className="small-link">Forgot password?</Link></div><button className="btn primary full" disabled={busy}>{busy?'Signing in…':'Sign in'}</button><p className="muted center">New to UniEvents? <Link to="/register" className="small-link">Create an account</Link></p><div className="demo-box"><b>Demo accounts</b><span>Student · student@bbdu.ac.in</span><span>Faculty · faculty@bbdu.ac.in</span><span>Club · club@bbdu.ac.in</span><span>Admin · admin@bbdu.ac.in</span><small>Password for all: <b>UniEvents@123</b></small></div></form></div></div>}
const navByRole={student:[['Discover',Compass,'/'],['My Events',CalendarDays,'/my-events'],['Profile',UserCircle,'/profile']],faculty:[['Overview',LayoutDashboard,'/'],['Create Event',Plus,'/create'],['My Events',CalendarDays,'/my-events'],['Reports',ChartNoAxesCombined,'/reports']],club:[['Overview',LayoutDashboard,'/'],['Create Event',Plus,'/create'],['My Events',CalendarDays,'/my-events'],['Reports',ChartNoAxesCombined,'/reports']],admin:[['Overview',LayoutDashboard,'/'],['All Events',CalendarDays,'/all-events'],['Pending Approvals',CheckCheck,'/pending'],['Users',Users,'/users'],['Clubs',Building2,'/clubs'],['Categories',Tags,'/categories'],['Announcements',Bell,'/announcements'],['Reports',ChartNoAxesCombined,'/reports'],['Audit Log',ShieldCheck,'/audit']]};
function Shell(){const{user,logout,switchRole}=useAuth(),[collapsed,setCollapsed]=useState(false),[notif,setNotif]=useState(false),[unread,setUnread]=useState(0),[pend,setPend]=useState(0);const loc=useLocation(),nav=useNavigate();useEffect(()=>{api.get('/notifications').then(x=>setUnread(x.unread||0)).catch(()=>{});if(user.role==='admin')api.get('/events/pending').then(x=>setPend(x.items.length)).catch(()=>{})},[loc.pathname,user.role]);const links=[...(navByRole[user.role]||navByRole.student)];if(!links.some(l=>l[2]==='/profile'))links.push(['Profile',UserCircle,'/profile']);return <div className="app-shell"><aside className={`sidebar ${collapsed?'collapsed':''}`}><div className="brand"><span className="brand-mark">U</span>{!collapsed&&'UniEvents'}</div><div className="side-label">WORKSPACE</div><nav>{links.map(([label,Icon,path])=><Link key={path} to={path} className={`nav-link ${loc.pathname===path?'active':''}`}><Icon size={18}/>{!collapsed&&<span>{label}</span>}{label==='Pending Approvals'&&pend>0&&<span className="nav-count">{pend}</span>}</Link>)}</nav><div className="side-bottom"><div className="user-mini"><div className="avatar">{initials(user.name)}</div>{!collapsed&&<div><b>{user.name}</b><small>{roles[user.role]}</small></div>}</div><button className="icon-btn" title="Sign out" onClick={logout}><LogOut size={17}/></button></div></aside><main className="main-area"><header className="topbar"><button className="icon-btn" onClick={()=>setCollapsed(!collapsed)}><Menu size={19}/></button><div className="top-spacer"/>{user.roles?.length>1&&<select className="role-switch" title="Switch workspace" value={user.role} onChange={async e=>{try{await switchRole(e.target.value);nav('/')}catch(x){console.error(x)}}}>{user.roles.map(r=><option key={r} value={r}>{roles[r]}</option>)}</select>}<span className="term-label">Academic Session 2026–2027</span><button className="icon-btn notification-btn" onClick={()=>setNotif(!notif)}><Bell size={19}/>{unread>0&&<i/>}</button><div className="top-avatar">{initials(user.name)}</div></header>{notif&&<NotificationPanel close={()=>setNotif(false)} refresh={()=>api.get('/notifications').then(x=>setUnread(x.unread||0))}/>}<div className="page-content"><RoutesView/></div></main></div>}
function NotificationPanel({close,refresh}){const[items,setItems]=useState([]);useEffect(()=>{api.get('/notifications').then(x=>setItems(x.items))},[]);const read=async id=>{await api.put(`/notifications/${id}/read`);setItems(a=>a.map(n=>n._id===id?{...n,isRead:true}:n));refresh()};return <div className="notification-panel"><div className="row-between"><b>Notifications</b><button className="text-btn" onClick={async()=>{await api.put('/notifications/read-all');setItems(a=>a.map(n=>({...n,isRead:true})));refresh()}}>Mark all read</button><button className="icon-btn" onClick={close}>×</button></div>{items.length?items.map(n=><button className={`notice ${n.isRead?'':'unread'}`} key={n._id} onClick={()=>read(n._id)}><b>{n.title}</b><span>{n.message}</span><small>{datetime(n.createdAt)}</small></button>):<div className="empty">You're all caught up.</div>}</div>}
function RoutesView(){const{user}=useAuth();if(user.role==='student')return <StudentRoutes/>;if(user.role==='admin')return <AdminRoutes/>;return <OrganizerRoutes/>}
function StudentRoutes(){return <Routes><Route path="/" element={<Discover/>}/><Route path="/event/:id" element={<EventDetail/>}/><Route path="/my-events" element={<MyEvents/>}/><Route path="/profile" element={<Profile/>}/><Route path="*" element={<Discover/>}/></Routes>}
function OrganizerRoutes(){return <Routes><Route path="/" element={<OrganizerDashboard/>}/><Route path="/event/:id" element={<EventDetail/>}/><Route path="/create" element={<EventForm/>}/><Route path="/edit/:id" element={<EventForm/>}/><Route path="/my-events" element={<OrganizerEvents/>}/><Route path="/manage/:id" element={<ManageEvent/>}/><Route path="/reports" element={<Reports/>}/><Route path="/profile" element={<Profile/>}/><Route path="*" element={<OrganizerDashboard/>}/></Routes>}
function AdminRoutes(){return <Routes><Route path="/" element={<AdminDashboard/>}/><Route path="/all-events" element={<AdminEvents/>}/><Route path="/event/:id" element={<EventDetail/>}/><Route path="/pending" element={<Pending/>}/><Route path="/users" element={<UsersPage/>}/><Route path="/clubs" element={<SimpleAdmin type="clubs"/>}/><Route path="/categories" element={<SimpleAdmin type="categories"/>}/><Route path="/announcements" element={<Announcements/>}/><Route path="/reports" element={<Reports/>}/><Route path="/audit" element={<Audit/>}/><Route path="/profile" element={<Profile/>}/><Route path="*" element={<AdminDashboard/>}/></Routes>}
function PageTitle({eyebrow,title,sub,action}){return <div className="page-title"><div><span className="eyebrow">{eyebrow}</span><h1>{title}</h1>{sub&&<p>{sub}</p>}</div>{action}</div>}
function Stat({label,value,icon:Icon,detail}){return <div className="stat-card"><div className="stat-top"><span>{label}</span><span className="stat-icon"><Icon size={18}/></span></div><strong>{value??'—'}</strong>{detail&&<small>{detail}</small>}</div>}
function Status({value}){const c=(value||'').toLowerCase().replaceAll(' ','-');return <span className={`status ${c}`}>{value}</span>}
function EventCard({event}){return <Link to={`/event/${event._id}`} className="event-card"><div className="event-cover"><span className="category-pill">{event.category?.name||'Campus event'}</span><CalendarDays size={34}/></div><div className="event-card-body"><div className="row-between"><span className="muted tiny">{date(event.startAt)}</span><Status value={event.status}/></div><h3>{event.title}</h3><p>{event.summary}</p><div className="event-meta"><span><MapPin size={14}/>{event.venue}</span><span><Users size={14}/>{event.registeredCount||0}/{event.capacity}</span></div><div className="capacity"><i style={{width:`${Math.min(100,100*(event.registeredCount||0)/(event.capacity||1))}%`}}/></div></div></Link>}
function Discover(){const[events,setEvents]=useState([]),[featured,setFeatured]=useState([]),[cats,setCats]=useState([]),[q,setQ]=useState(''),[category,setCategory]=useState(''),[busy,setBusy]=useState(true);const load=()=>{setBusy(true);api.get('/events',{params:{q,category,upcoming:'true',limit:50}}).then(x=>setEvents(x.items)).catch(console.error).finally(()=>setBusy(false));api.get('/events/featured').then(x=>setFeatured(x.items)).catch(()=>{});api.get('/categories').then(x=>setCats(x.items)).catch(()=>{})};useEffect(()=>{load()},[q,category]);const hero=featured[0]||events[0];return <><PageTitle eyebrow="YOUR CAMPUS CALENDAR" title="Discover events" sub="Find your next opportunity to learn, connect and participate."/><div className="search-row"><div className="search-box"><Search size={18}/><input placeholder="Search events, topics or venues…" value={q} onChange={e=>setQ(e.target.value)}/></div><select value={category} onChange={e=>setCategory(e.target.value)}><option value="">All categories</option>{cats.map(c=><option value={c._id} key={c._id}>{c.name}</option>)}</select></div>{hero&&<div className="hero-event"><div><span className="eyebrow">FEATURED EVENT</span><h2>{hero.title}</h2><p>{hero.summary}</p><div className="hero-meta"><span><CalendarDays size={15}/>{date(hero.startAt)}</span><span><MapPin size={15}/>{hero.venue}</span></div><Link className="btn light" to={`/event/${hero._id}`}>Explore event <ChevronRight size={16}/></Link></div><div className="hero-art"><CalendarDays size={100}/><span>UNIEVENTS</span></div></div>}<div className="section-head"><div><h2>Upcoming events</h2><p>Explore what's happening around campus.</p></div><span className="muted small">{events.length} events</span></div>{busy?<div className="loading">Loading events…</div>:events.length?<div className="event-grid">{events.map(e=><EventCard event={e} key={e._id}/>)}</div>:<Empty title="No events yet" text="Check back soon for new campus events."/>}</>}
function EventDetail(){const{user}=useAuth(),{id}=useParamsSafe(),[event,setEvent]=useState(null),[registration,setRegistration]=useState(null),[error,setError]=useState(''),[loadError,setLoadError]=useState(''),[busy,setBusy]=useState(false);const load=()=>api.get(`/events/${id}`).then(x=>{setEvent(x.event);setRegistration(x.registration)}).catch(e=>setLoadError(e.message));useEffect(()=>{load()},[id]);if(loadError)return <><Link to="/" className="back-link">← Back</Link><div className="alert error">{loadError}</div></>;if(!event)return <div className="loading">Loading event…</div>;const act=async()=>{setBusy(true);setError('');try{if(registration)await api.delete(`/events/${id}/register`);else{const x=await api.post(`/events/${id}/register`);setRegistration(x.registration)}load()}catch(e){setError(e.message)}finally{setBusy(false)}};const full=event.registeredCount>=event.capacity,isStudent=user.role==='student',canWait=full&&event.waitlistEnabled;return <><Link to="/" className="back-link">← Back to discover</Link><div className="detail-layout"><div><div className="detail-cover"><CalendarDays size={64}/><span>{event.category?.name}</span></div><div className="detail-main"><Status value={event.status}/><h1>{event.title}</h1><p className="lead">{event.summary}</p><h3>About this event</h3><p className="description">{event.description}</p><div className="detail-facts"><div><CalendarDays/><span><b>Date and time</b>{datetime(event.startAt)} – {datetime(event.endAt)}</span></div><div><MapPin/><span><b>Venue</b>{event.venue}</span></div><div><Users/><span><b>Organizer</b>{event.organizer?.name||'University'}</span></div></div></div></div><aside className="register-card"><span className="eyebrow">REGISTRATION</span><h2>{event.registeredCount} <small>/ {event.capacity}</small></h2><p className="muted">Seats registered</p><div className="capacity large"><i style={{width:`${Math.min(100,event.registeredCount/event.capacity*100)}%`}}/></div><div className="fact-line"><span>Registration deadline</span><b>{date(event.registrationDeadline)}</b></div>{!isStudent?<Link className="btn secondary full" to={`/manage/${event._id}`}>Manage this event</Link>:registration?<><Status value={registration.status}/><button className="btn danger full" onClick={act} disabled={busy}>{registration.status==='Waitlisted'?'Leave waitlist':'Cancel registration'}</button></>:<button className="btn primary full" onClick={act} disabled={busy||(full&&!event.waitlistEnabled)||!['Approved','Ongoing'].includes(event.status)}>{busy?'Please wait':canWait?'Join waitlist':full?'Registration full':'Register now'}</button>}<small className="muted">Registration is subject to eligibility and availability.</small>{error&&<div className="alert error">{error}</div>}</aside></div></>}
function useParamsSafe(){return useParams()}
function MyEvents(){const[items,setItems]=useState([]);useEffect(()=>{api.get('/registrations/me').then(x=>setItems(x.items)).catch(console.error)},[]);return <><PageTitle eyebrow="YOUR ACTIVITY" title="My Events" sub="Your registrations and event participation."/><div className="table-card"><table><thead><tr><th>Event</th><th>Date</th><th>Venue</th><th>Registration</th></tr></thead><tbody>{items.map(r=><tr key={r._id}><td>{r.event?<Link to={`/event/${r.event._id}`}><b>{r.event.title}</b></Link>:<b>Removed event</b>}</td><td>{date(r.event?.startAt)}</td><td>{r.event?.venue||'—'}</td><td><Status value={r.status}/></td></tr>)}</tbody></table>{!items.length&&<Empty title="No registrations yet" text="Discover events and register to see them here."/>}</div></>}
function OrganizerDashboard(){const[items,setItems]=useState([]);useEffect(()=>{api.get('/events/mine').then(x=>setItems(x.items)).catch(()=>{})},[]);const pending=items.filter(e=>e.status==='Pending').length;return <><PageTitle eyebrow="EVENT MANAGEMENT" title="Overview" sub="Manage your events and keep track of participation." action={<Link className="btn primary" to="/create"><Plus size={16}/> Create event</Link>}/><div className="stats-grid"><Stat label="Total events" value={items.length} icon={CalendarDays}/><Stat label="Pending review" value={pending} icon={Clock}/><Stat label="Registrations" value={items.reduce((a,e)=>a+e.registeredCount,0)} icon={Users}/><Stat label="Completed" value={items.filter(e=>e.status==='Completed').length} icon={CheckCircle2}/></div><div className="section-head"><div><h2>Recent events</h2><p>Your latest event submissions.</p></div><Link to="/my-events" className="text-btn">View all</Link></div><div className="table-card"><EventTable items={items.slice(0,8)} manage/></div></>}
