function EventTable({items,manage=false}){return <table><thead><tr><th>Event</th><th>Date</th><th>Registrations</th><th>Status</th>{manage&&<th>Actions</th>}</tr></thead><tbody>{items.map(e=><tr key={e._id}><td><Link to={`/event/${e._id}`}><b>{e.title}</b></Link><small className="block muted">{e.category?.name}</small></td><td>{date(e.startAt)}</td><td>{e.registeredCount}/{e.capacity}</td><td><Status value={e.status}/></td>{manage&&<td><Link className="text-btn" to={`/manage/${e._id}`}>Manage</Link> · <Link className="text-btn" to={`/edit/${e._id}`}>Edit</Link></td>}</tr>)}</tbody></table>}
function EventForm(){const nav=useNavigate(),loc=useLocation(),id=loc.pathname.startsWith('/edit/')?loc.pathname.split('/').pop():null;const[cats,setCats]=useState([]),[form,setForm]=useState({title:'',summary:'',description:'',category:'',venue:'',startAt:'',endAt:'',registrationDeadline:'',capacity:100}),[error,setError]=useState(''),[busy,setBusy]=useState(false);useEffect(()=>{api.get('/categories').then(x=>{setCats(x.items);if(!id&&x.items[0])setForm(f=>f.category?f:{...f,category:x.items[0]._id})}).catch(e=>setError(e.message));if(id)api.get(`/events/${id}`).then(x=>setForm({...x.event,category:x.event.category?._id||x.event.category,club:x.event.club?._id||x.event.club||undefined,startAt:toLocal(x.event.startAt),endAt:toLocal(x.event.endAt),registrationDeadline:toLocal(x.event.registrationDeadline)})).catch(e=>setError(e.message))},[id]);const change=e=>setForm(f=>({...f,[e.target.name]:e.target.value}));const save=async submit=>{setError('');const need=['title','summary','description','category','venue','startAt','endAt','registrationDeadline'];if(need.some(k=>!form[k]))return setError('Please fill in all fields marked with *.');const iso=v=>v?new Date(v).toISOString():undefined;const st=new Date(form.startAt),en=new Date(form.endAt),dl=new Date(form.registrationDeadline);if(en<=st)return setError('The end time must be after the start time.');if(dl>st)return setError('The registration deadline must be on or before the start time.');setBusy(true);try{const payload={...form,startAt:iso(form.startAt),endAt:iso(form.endAt),registrationDeadline:iso(form.registrationDeadline),capacity:Number(form.capacity)};let x;if(id)x=await api.put(`/events/${id}`,payload);else x=await api.post('/events',payload);if(submit&&(!id||['Draft','Changes Requested','Rejected'].includes(form.status)))await api.post(`/events/${x.event._id}/submit`);nav('/my-events')}catch(e){setError(e.message)}finally{setBusy(false)}};return <><PageTitle eyebrow="EVENT MANAGEMENT" title={id?'Edit event':'Create a new event'} sub="Add the event information and submit it for administrative review."/><form className="form-card" onSubmit={e=>{e.preventDefault();save(false)}}><div className="form-grid"><label>Event title *<input name="title" value={form.title} onChange={change} required maxLength="120"/></label><label>Category *<select name="category" value={form.category} onChange={change} required>{cats.map(c=><option key={c._id} value={c._id}>{c.name}</option>)}</select></label><label className="span2">Short summary *<input name="summary" value={form.summary} onChange={change} required maxLength="240"/></label><label className="span2">Description *<textarea name="description" value={form.description} onChange={change} rows="5" required maxLength="5000"/></label><label>Venue *<input name="venue" value={form.venue} onChange={change} required/></label><label>Capacity *<input name="capacity" type="number" min="1" value={form.capacity} onChange={change} required/></label><label>Start date and time *<input name="startAt" type="datetime-local" value={form.startAt} onChange={change} required/></label><label>End date and time *<input name="endAt" type="datetime-local" value={form.endAt} onChange={change} required/></label><label>Registration deadline *<input name="registrationDeadline" type="datetime-local" value={form.registrationDeadline} onChange={change} required/></label><label className="check-label"><input type="checkbox" checked={!!form.waitlistEnabled} onChange={e=>setForm(f=>({...f,waitlistEnabled:e.target.checked}))}/> Enable a waitlist when the event is full</label></div>{form.status==='Changes Requested'&&form.reviewComment&&<div className="alert error">Changes requested by the administrator: {form.reviewComment}</div>}{form.status==='Rejected'&&form.rejectionReason&&<div className="alert error">Rejected: {form.rejectionReason}</div>}{error&&<div className="alert error">{error}</div>}<div className="form-actions"><button type="button" className="btn secondary" disabled={busy} onClick={()=>save(false)}>Save draft</button><button type="button" className="btn primary" disabled={busy} onClick={()=>save(true)}>Submit for approval</button></div></form></>}
function toLocal(d){if(!d)return'';const x=new Date(d);return new Date(x.getTime()-x.getTimezoneOffset()*60000).toISOString().slice(0,16)}
function ManageEvent(){const{id}=useParamsSafe(),[event,setEvent]=useState(null),[people,setPeople]=useState([]),[error,setError]=useState(''),[ask,setAsk]=useState(false);const load=()=>{api.get(`/events/${id}`).then(x=>setEvent(x.event)).catch(e=>setError(e.message));api.get(`/events/${id}/participants`).then(x=>setPeople(x.items)).catch(e=>setError(e.message))};useEffect(()=>{load()},[id]);const attendance=async(r,status)=>{try{await api.put(`/registrations/${r._id}/attendance`,{status});load()}catch(e){setError(e.message)}};const submitEvent=async()=>{try{await api.post(`/events/${id}/submit`);load()}catch(e){setError(e.message)}};const completeEvent=async()=>{try{await api.put(`/events/${id}/complete`);load()}catch(e){setError(e.message)}};const exportCsv=()=>{const q=v=>`"${String(v??'').replace(/"/g,'""')}"`;const rows=[['Name','Email','Roll number','Department','Year','Status'],...people.map(r=>[r.student?.name,r.student?.email,r.student?.rollNumber,r.student?.department,r.student?.year,r.status])];const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([rows.map(x=>x.map(q).join(',')).join('\n')],{type:'text/csv'}));a.download='participants.csv';a.click();URL.revokeObjectURL(a.href)};if(!event)return <div className="loading">{error||'Loading…'}</div>;return <><PageTitle eyebrow="EVENT OPERATIONS" title={event.title} sub={`${event.venue} · ${date(event.startAt)}`}/><div className="manage-actions"><Link className="btn secondary" to={`/event/${event._id}`}>View event page</Link><Link className="btn secondary" to={`/edit/${event._id}`}>Edit</Link>{['Draft','Changes Requested','Rejected'].includes(event.status)&&<button className="btn primary" onClick={submitEvent}>Submit for approval</button>}{['Approved','Ongoing'].includes(event.status)&&new Date()>=new Date(event.endAt)&&<button className="btn primary" onClick={completeEvent}>Close event</button>}{!['Completed','Cancelled','Archived'].includes(event.status)&&<button className="btn danger-outline" onClick={()=>setAsk(true)}>Cancel event</button>}<button className="btn secondary" onClick={exportCsv} disabled={!people.length}>Export participants (CSV)</button></div>{ask&&<AskModal title="Cancel this event" label="Reason (shown to registered students)" min={5} confirmText="Cancel event" onSubmit={async t=>{await api.put(`/events/${id}/cancel`,{reason:t});load()}} onClose={()=>setAsk(false)}/>}{error&&<div className="alert error">{error}</div>}<div className="stats-grid"><Stat label="Registered" value={event.registeredCount} icon={Users}/><Stat label="Capacity" value={event.capacity} icon={CalendarDays}/><Stat label="Status" value={event.status} icon={CheckCircle2}/></div><div className="section-head"><div><h2>Participants and attendance</h2><p>Mark each registered participant as attended or not attended.</p></div></div><div className="table-card"><table><thead><tr><th>Student</th><th>Roll number</th><th>Department</th><th>Status</th><th>Attendance</th></tr></thead><tbody>{people.map(r=><tr key={r._id}><td>{r.student?.name}</td><td>{r.student?.rollNumber}</td><td>{r.student?.department}</td><td><Status value={r.status}/></td><td><button className="btn tiny secondary" disabled={['Waitlisted','Cancelled'].includes(r.status)} onClick={()=>attendance(r,'Attended')}>Present</button> <button className="btn tiny secondary" disabled={['Waitlisted','Cancelled'].includes(r.status)} onClick={()=>attendance(r,'Not attended')}>Absent</button></td></tr>)}</tbody></table>{!people.length&&<Empty title="No registrations yet" text="Participants will appear here after they register."/>}</div></>}
function AdminDashboard(){const[stats,setStats]=useState({}),[recent,setRecent]=useState([]);useEffect(()=>{api.get('/admin/overview').then(x=>{setStats(x.stats);setRecent(x.recent)})},[]);return <><PageTitle eyebrow="UNIVERSITY OVERVIEW" title="Administration" sub="Monitor campus events, registrations and approval activity."/><div className="stats-grid"><Stat label="Active users" value={stats.users} icon={Users}/><Stat label="Total events" value={stats.events} icon={CalendarDays}/><Stat label="Pending approvals" value={stats.pending} icon={Clock}/><Stat label="Registrations" value={stats.registrations} icon={ClipboardList}/></div><div className="section-head"><div><h2>Recent activity</h2><p>Latest events across the university.</p></div><Link to="/all-events" className="text-btn">All events</Link></div><div className="table-card"><table><thead><tr><th>Event</th><th>Organizer</th><th>Created</th><th>Status</th></tr></thead><tbody>{recent.map(e=><tr key={e._id}><td><b>{e.title}</b></td><td>{e.organizer?.name}</td><td>{date(e.createdAt)}</td><td><Status value={e.status}/></td></tr>)}</tbody></table></div></>}
function AdminEvents(){const[items,setItems]=useState([]);useEffect(()=>{api.get('/events',{params:{scope:'all',limit:50}}).then(x=>setItems(x.items)).catch(()=>{})},[]);return <><PageTitle eyebrow="EVENT DIRECTORY" title="All Events" sub="University-wide event directory."/><div className="table-card"><EventTable items={items}/></div></>}
function Pending(){const[items,setItems]=useState([]),[error,setError]=useState(''),[ask,setAsk]=useState(null);const load=()=>api.get('/events/pending').then(x=>setItems(x.items)).catch(e=>setError(e.message));useEffect(()=>{load()},[]);const approve=async id=>{try{await api.put(`/events/${id}/approve`);load()}catch(e){setError(e.message)}};return <><PageTitle eyebrow="REVIEW QUEUE" title="Pending Approvals" sub="Review submissions before they become visible to students."/>{ask&&<AskModal title={ask.action==='reject'?'Reject event':'Request changes'} label={ask.action==='reject'?'Reason for rejection (minimum 20 characters)':'Requested changes (minimum 10 characters)'} min={ask.action==='reject'?20:10} confirmText={ask.action==='reject'?'Reject event':'Send request'} onSubmit={async t=>{await api.put(`/events/${ask.id}/${ask.action}`,ask.action==='reject'?{reason:t}:{comment:t});load()}} onClose={()=>setAsk(null)}/>}{error&&<div className="alert error">{error}</div>}<div className="review-list">{items.map(e=><div className="review-card" key={e._id}><div className="row-between"><Status value={e.status}/><small className="muted">Submitted {date(e.submittedAt)}</small></div><h3><Link to={`/event/${e._id}`}>{e.title}</Link></h3><p>{e.summary}</p><div className="event-meta"><span><Users size={14}/>{e.organizer?.name}</span><span><CalendarDays size={14}/>{date(e.startAt)}</span><span><MapPin size={14}/>{e.venue}</span></div><div className="review-actions"><button className="btn secondary" onClick={()=>setAsk({id:e._id,action:'request-changes'})}>Request changes</button><button className="btn danger-outline" onClick={()=>setAsk({id:e._id,action:'reject'})}>Reject</button><button className="btn primary" onClick={()=>approve(e._id)}>Approve event</button></div></div>)}{!items.length&&<Empty title="All caught up" text="There are no events awaiting approval."/>}</div></>}
function UsersPage(){const[items,setItems]=useState([]),[error,setError]=useState(''),[showNew,setShowNew]=useState(false),[nu,setNu]=useState({name:'',email:'',role:'faculty',department:'',password:''});const addStaff=async e=>{e.preventDefault();setError('');try{await api.post('/users',nu);setNu({name:'',email:'',role:'faculty',department:'',password:''});setShowNew(false);load()}catch(x){setError(x.message)}};const load=()=>api.get('/users').then(x=>setItems(x.items)).catch(e=>setError(e.message));useEffect(()=>{load()},[]);const toggle=async u=>{try{await api.put(`/users/${u._id}/status`,{isActive:!u.isActive});load()}catch(e){setError(e.message)}};return <><PageTitle eyebrow="ACCESS MANAGEMENT" title="Users" sub="Manage university accounts and workspace access." action={<button className="btn primary" onClick={()=>setShowNew(!showNew)}><Plus size={16}/> Add staff account</button>}/>{error&&<div className="alert error">{error}</div>}{showNew&&<form className="form-card" onSubmit={addStaff}><div className="form-grid"><label>Full name *<input value={nu.name} onChange={e=>setNu({...nu,name:e.target.value})} required minLength="2" maxLength="60"/></label><label>University e-mail *<input type="email" value={nu.email} onChange={e=>setNu({...nu,email:e.target.value})} required/></label><label>Role *<select value={nu.role} onChange={e=>setNu({...nu,role:e.target.value})}><option value="faculty">Faculty</option><option value="club">Club organizer</option><option value="admin">Administrator</option></select></label><label>Department<input value={nu.department} onChange={e=>setNu({...nu,department:e.target.value})}/></label><label className="span2">Initial password (leave blank for Welcome@123)<input type="text" value={nu.password} onChange={e=>setNu({...nu,password:e.target.value})}/></label></div><div className="form-actions"><button type="button" className="btn secondary" onClick={()=>setShowNew(false)}>Cancel</button><button className="btn primary">Create account</button></div></form>}<div className="table-card"><table><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Department</th><th>Status</th><th>Action</th></tr></thead><tbody>{items.map(u=><tr key={u._id}><td><b>{u.name}</b></td><td>{u.email}</td><td>{roles[u.role]}</td><td>{u.department}</td><td><Status value={u.isActive?'Active':'Inactive'}/></td><td><button className="text-btn" onClick={()=>toggle(u)}>{u.isActive?'Deactivate':'Activate'}</button></td></tr>)}</tbody></table></div></>}
function SimpleAdmin({type}){const[items,setItems]=useState([]),[name,setName]=useState(''),[error,setError]=useState('');const load=()=>api.get(`/${type}`).then(x=>setItems(x.items)).catch(e=>setError(e.message));useEffect(()=>{load()},[type]);const off=async x=>{try{await api.put(`/${type}/${x._id}`,{isActive:false});load()}catch(e){setError(e.message)}};const add=async e=>{e.preventDefault();try{await api.post(`/${type}`,type==='categories'?{name,colour:'#6558d3'}:{name,description:'University student club'});setName('');load()}catch(e){setError(e.message)}};return <><PageTitle eyebrow="SYSTEM CONFIGURATION" title={type==='clubs'?'Clubs':'Event Categories'} sub="Maintain the groups and categories used by UniEvents."/><form className="inline-add" onSubmit={add}><input value={name} onChange={e=>setName(e.target.value)} placeholder={type==='clubs'?'Club name':'Category name'} required/><button className="btn primary">Add</button></form>{error&&<div className="alert error">{error}</div>}<div className="table-card"><table><thead><tr><th>Name</th><th>Description / Colour</th><th>Status</th><th>Action</th></tr></thead><tbody>{items.map(x=><tr key={x._id}><td><b>{x.name}</b></td><td>{x.description||x.colour}</td><td><Status value={x.isActive?'Active':'Inactive'}/></td><td><button className="text-btn" onClick={()=>off(x)}>Deactivate</button></td></tr>)}</tbody></table></div></>}
function Announcements(){const[title,setTitle]=useState(''),[message,setMessage]=useState(''),[audience,setAudience]=useState('all'),[urgent,setUrgent]=useState(false),[done,setDone]=useState(''),[error,setError]=useState('');const send=async e=>{e.preventDefault();setDone('');setError('');try{const x=await api.post('/announcements',{title,message,audience,urgent});setDone(`Announcement delivered to ${x.recipients} users.`);setTitle('');setMessage('')}catch(e){setError(e.message)}};return <><PageTitle eyebrow="COMMUNICATION" title="Announcements" sub="Send university-wide or role-specific announcements."/><form className="form-card narrow" onSubmit={send}><label>Announcement title<input value={title} onChange={e=>setTitle(e.target.value)} required maxLength="120"/></label><label>Message<textarea rows="5" value={message} onChange={e=>setMessage(e.target.value)} required maxLength="1000"/></label><label>Audience<select value={audience} onChange={e=>setAudience(e.target.value)}><option value="all">Everyone</option><option value="student">Students</option><option value="faculty">Faculty</option><option value="club">Club organizers</option></select></label><label className="check-label"><input type="checkbox" checked={urgent} onChange={e=>setUrgent(e.target.checked)}/> Mark as urgent</label>{error&&<div className="alert error">{error}</div>}{done&&<div className="alert success">{done}</div>}<button className="btn primary">Send announcement</button></form></>}
function Reports(){const[data,setData]=useState(null),[type,setType]=useState('events'),[range,setRange]=useState({from:'',to:''}),[error,setError]=useState('');const params={from:range.from||undefined,to:range.to||undefined};useEffect(()=>{setError('');api.get(`/reports/${type}`,{params}).then(x=>setData(x.data)).catch(e=>setError(e.message))},[type,range.from,range.to]);const exportCsv=async()=>{try{const blob=await api.get(`/reports/${type}/export`,{params,responseType:'blob'});const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([blob],{type:'text/csv'}));a.download='unievents-report.csv';a.click();URL.revokeObjectURL(a.href)}catch(e){setError(e.message)}};const Bars=({title,rows})=><div className="table-card pad"><h3>{title}</h3>{rows.length?rows.map(x=><div className="bar-row" key={x.name}><span>{x.name}</span><div className="bar"><i style={{width:`${100*x.value/Math.max(1,...rows.map(y=>y.value))}%`}}/></div><b>{x.value}</b></div>):<p className="muted">No data for this period.</p>}</div>;const done=data?data.events.filter(e=>['Completed','Archived'].includes(e.status)):[];return <><PageTitle eyebrow="INSIGHTS & PERFORMANCE" title="Reports and Analytics" sub="Review event activity and participation using stored system data." action={<button className="btn secondary" onClick={exportCsv}><FileText size={16}/> Export CSV</button>}/><div className="tabs">{['events','registrations','attendance','trends','organizers'].map(t=><button className={type===t?'selected':''} onClick={()=>setType(t)} key={t}>{t[0].toUpperCase()+t.slice(1)}</button>)}</div><div className="inline-add"><label className="small">From <input type="date" value={range.from} onChange={e=>setRange({...range,from:e.target.value})}/></label><label className="small">To <input type="date" value={range.to} onChange={e=>setRange({...range,to:e.target.value})}/></label>{(range.from||range.to)&&<button className="text-btn" onClick={()=>setRange({from:'',to:''})}>Clear dates</button>}</div>{error&&<div className="alert error">{error}</div>}{data&&<><div className="stats-grid"><Stat label="Events" value={data.summary.events} icon={CalendarDays}/><Stat label="Registrations" value={data.summary.registrations} icon={Users}/><Stat label="Completed" value={data.summary.completed} icon={CheckCircle2}/><Stat label="Attendance rate" value={`${data.summary.attendanceRate}%`} icon={ChartNoAxesCombined}/></div>{type==='events'&&<><div className="two-col"><Bars title="Events by status" rows={data.byStatus}/><Bars title="Events by category" rows={data.byCategory}/></div><div className="table-card"><table><thead><tr><th>Event</th><th>Date</th><th>Capacity</th><th>Registered</th><th>Status</th></tr></thead><tbody>{data.events.map((e,i)=><tr key={i}><td>{e.title}</td><td>{date(e.startAt)}</td><td>{e.capacity}</td><td>{e.registeredCount}</td><td><Status value={e.status}/></td></tr>)}</tbody></table></div></>}{type==='registrations'&&<><div className="two-col"><Bars title="Registrations by status" rows={data.registrationsByStatus}/><Bars title="Fill rate by event (%)" rows={data.events.map(e=>({name:e.title,value:e.fillRate}))}/></div><div className="table-card"><table><thead><tr><th>Event</th><th>Capacity</th><th>Registered</th><th>Waitlisted</th><th>Fill rate</th></tr></thead><tbody>{data.events.map((e,i)=><tr key={i}><td>{e.title}</td><td>{e.capacity}</td><td>{e.registeredCount}</td><td>{e.waitlisted}</td><td>{e.fillRate}%</td></tr>)}</tbody></table></div></>}{type==='attendance'&&<div className="table-card"><table><thead><tr><th>Event</th><th>Date</th><th>Registered</th><th>Attended</th><th>Absent</th><th>Attendance</th></tr></thead><tbody>{done.map((e,i)=><tr key={i}><td>{e.title}</td><td>{date(e.startAt)}</td><td>{e.registeredCount}</td><td>{e.attended}</td><td>{e.absent}</td><td>{e.attended+e.absent?Math.round(100*e.attended/(e.attended+e.absent))+'%':'—'}</td></tr>)}</tbody></table>{!done.length&&<Empty title="No completed events" text="Attendance appears here once events are completed."/>}</div>}{type==='trends'&&<div className="two-col"><Bars title="Events per month" rows={data.trend}/><Bars title="Events by category" rows={data.byCategory}/></div>}{type==='organizers'&&<div className="table-card"><table><thead><tr><th>Organizer</th><th>Events</th><th>Registrations</th></tr></thead><tbody>{data.organizers.map(o=><tr key={o.name}><td>{o.name}</td><td>{o.events}</td><td>{o.registrations}</td></tr>)}</tbody></table>{!data.organizers.length&&<Empty title="No data" text="No events in this period."/>}</div>}</>}</>}

function Audit(){const[items,setItems]=useState([]);useEffect(()=>{api.get('/admin/audit').then(x=>setItems(x.items)).catch(()=>{})},[]);return <><PageTitle eyebrow="SECURITY & GOVERNANCE" title="Audit Log" sub="Read-only history of administrative actions."/><div className="table-card"><table><thead><tr><th>Time</th><th>User</th><th>Action</th><th>Target</th></tr></thead><tbody>{items.map(x=><tr key={x._id}><td>{datetime(x.createdAt)}</td><td>{x.user?.name||'System'}</td><td>{x.action}</td><td>{x.targetType}</td></tr>)}</tbody></table></div></>}
function Profile(){const{user,setUser}=useAuth(),pr=user.notificationPreferences||{};const[form,setForm]=useState({name:user.name,phone:user.phone||'',bio:user.bio||'',department:user.department||'',year:user.year||'',notificationPreferences:{reminders:pr.reminders!==false,updates:pr.updates!==false,announcements:pr.announcements!==false}}),[pw,setPw]=useState({currentPassword:'',newPassword:'',confirmPassword:''}),[message,setMessage]=useState(''),[error,setError]=useState(''),[pwMsg,setPwMsg]=useState(''),[pwErr,setPwErr]=useState('');const save=async e=>{e.preventDefault();setMessage('');setError('');try{const x=await api.put('/profile',form);setUser(x.user);setMessage('Your profile has been updated.')}catch(e){setError(e.message)}};const changePw=async e=>{e.preventDefault();setPwMsg('');setPwErr('');try{const x=await api.put('/profile/password',pw);setPwMsg(x.message);setPw({currentPassword:'',newPassword:'',confirmPassword:''})}catch(e){setPwErr(e.message)}};const pref=(k,label)=><label className="check-label"><input type="checkbox" checked={form.notificationPreferences[k]} onChange={e=>setForm(f=>({...f,notificationPreferences:{...f.notificationPreferences,[k]:e.target.checked}}))}/> {label}</label>;return <><PageTitle eyebrow="ACCOUNT" title="Profile and Settings" sub="Manage your personal information, notifications and password."/><form className="form-card narrow" onSubmit={save}><div className="profile-head"><div className="avatar big">{initials(user.name)}</div><div><h2>{user.name}</h2><Status value={roles[user.role]}/><p className="muted">{user.email}</p></div></div><label>Full name<input value={form.name} onChange={e=>setForm(f=>({...f,name:e.target.value}))} required minLength="2" maxLength="60"/></label><label>Phone number<input value={form.phone} onChange={e=>setForm(f=>({...f,phone:e.target.value}))} maxLength="10" inputMode="numeric" pattern="[0-9]{10}" title="Enter a 10-digit phone number"/></label><label>Department<input value={form.department} onChange={e=>setForm(f=>({...f,department:e.target.value}))}/></label><label>Year<input value={form.year} onChange={e=>setForm(f=>({...f,year:e.target.value}))}/></label><label>Bio<textarea rows="3" value={form.bio} onChange={e=>setForm(f=>({...f,bio:e.target.value}))} maxLength="200"/></label><h3>Notification preferences</h3>{pref('reminders','Event reminders')}{pref('updates','Event and registration updates')}{pref('announcements','University announcements')}{error&&<div className="alert error">{error}</div>}{message&&<div className="alert success">{message}</div>}<button className="btn primary">Save changes</button></form><form className="form-card narrow" onSubmit={changePw}><h3>Change password</h3><label>Current password<input type="password" value={pw.currentPassword} onChange={e=>setPw({...pw,currentPassword:e.target.value})} required/></label><label>New password<input type="password" value={pw.newPassword} onChange={e=>setPw({...pw,newPassword:e.target.value})} required/></label><label>Confirm new password<input type="password" value={pw.confirmPassword} onChange={e=>setPw({...pw,confirmPassword:e.target.value})} required/></label><p className="muted small">8–20 characters with an upper-case letter, a lower-case letter, a digit and a special character.</p>{pwErr&&<div className="alert error">{pwErr}</div>}{pwMsg&&<div className="alert success">{pwMsg}</div>}<button className="btn primary">Update password</button></form></>}

function Empty({title,text}){return <div className="empty"><div className="empty-icon"><CalendarDays size={24}/></div><h3>{title}</h3><p>{text}</p></div>}
function AskModal({title,label,min=1,confirmText='Submit',onSubmit,onClose}){const[v,setV]=useState(''),[err,setErr]=useState(''),[busy,setBusy]=useState(false);const go=async e=>{e.preventDefault();if(v.trim().length<min)return setErr(`Please enter at least ${min} characters.`);setBusy(true);try{await onSubmit(v.trim());onClose()}catch(x){setErr(x.message);setBusy(false)}};return <div className="modal-backdrop" onClick={onClose}><form className="modal" onClick={e=>e.stopPropagation()} onSubmit={go}><h3>{title}</h3><label>{label}<textarea rows="4" value={v} onChange={e=>setV(e.target.value)} autoFocus/></label>{err&&<div className="alert error">{err}</div>}<div className="form-actions"><button type="button" className="btn secondary" onClick={onClose}>Close</button><button className="btn primary" disabled={busy}>{busy?'Please wait…':confirmText}</button></div></form></div>}

function AuthFrame({children}){return <div className="auth-page"><div className="auth-art"><div className="brand large"><span className="brand-mark">U</span> UniEvents</div><div className="art-copy"><span className="eyebrow">A MORE CONNECTED CAMPUS</span><h1>Every event.<br/>One university.</h1><p>Discover meaningful experiences and make campus life unforgettable.</p></div><div className="art-foot">Babu Banarasi Das University · Lucknow</div></div><div className="auth-side">{children}</div></div>}

const PW_RULE=/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[^A-Za-z\d]).{8,20}$/;

function Register(){const{setUser}=useAuth(),nav=useNavigate(),[f,setF]=useState({name:'',email:'',rollNumber:'',department:'Computer Science & Engineering',year:'1st Year',password:'',confirmPassword:''}),[error,setError]=useState(''),[busy,setBusy]=useState(false);const ch=e=>setF(x=>({...x,[e.target.name]:e.target.value}));const go=async e=>{e.preventDefault();setError('');if(!PW_RULE.test(f.password))return setError('Password must be 8–20 characters with an upper-case letter, a lower-case letter, a digit and a special character.');if(f.password!==f.confirmPassword)return setError('The passwords entered do not match.');setBusy(true);try{const x=await api.post('/auth/register',f);sessionStorage.removeItem('unievents_role');sessionStorage.setItem('unievents_token',x.token);setUser(x.user);nav('/')}catch(err){setError(err.message)}finally{setBusy(false)}};return <AuthFrame><form className="auth-card" onSubmit={go}><span className="eyebrow">JOIN UNIEVENTS</span><h2>Create your account</h2><p className="muted">Students sign up with their university e-mail address.</p>{error&&<div className="alert error">{error}</div>}<label>Full name<input name="name" value={f.name} onChange={ch} required minLength="2" maxLength="60"/></label><label>University email<input name="email" type="email" value={f.email} onChange={ch} required/></label><label>Roll number<input name="rollNumber" value={f.rollNumber} onChange={ch} required minLength="6" maxLength="15" pattern="[A-Za-z0-9]{6,15}" title="6 to 15 letters or digits"/></label><label>Department<input name="department" value={f.department} onChange={ch} required/></label><label>Year<select name="year" value={f.year} onChange={ch}>{['1st Year','2nd Year','3rd Year','4th Year'].map(y=><option key={y}>{y}</option>)}</select></label><label>Password<input name="password" type="password" value={f.password} onChange={ch} required/></label><label>Confirm password<input name="confirmPassword" type="password" value={f.confirmPassword} onChange={ch} required/></label><p className="muted small">8–20 characters with upper-case, lower-case, a digit and a special character.</p><button className="btn primary full" disabled={busy}>{busy?'Creating account…':'Create account'}</button><p className="muted center">Already registered? <Link to="/" className="small-link">Sign in</Link></p></form></AuthFrame>}

function Forgot(){const[email,setEmail]=useState(''),[res,setRes]=useState(null),[error,setError]=useState(''),[busy,setBusy]=useState(false);const go=async e=>{e.preventDefault();setError('');setBusy(true);try{setRes(await api.post('/auth/forgot-password',{email}))}catch(x){setError(x.message)}finally{setBusy(false)}};let token='';try{if(res?.resetUrl)token=new URL(res.resetUrl).searchParams.get('token')||''}catch{}return <AuthFrame><form className="auth-card" onSubmit={go}><span className="eyebrow">ACCOUNT RECOVERY</span><h2>Forgot your password?</h2><p className="muted">Enter your university e-mail address and we will send you a reset link.</p>{error&&<div className="alert error">{error}</div>}{res?<><div className="alert success">{res.message}</div>{token&&<div className="demo-box"><b>Demo mode</b><span>No mail server is configured, so the reset link is shown here.</span><Link className="btn primary full" to={`/reset?token=${token}`}>Open reset link</Link></div>}</>:<><label>University email<input type="email" value={email} onChange={e=>setEmail(e.target.value)} required/></label><button className="btn primary full" disabled={busy}>{busy?'Please wait…':'Send reset link'}</button></>}<p className="muted center"><Link to="/" className="small-link">Back to sign in</Link></p></form></AuthFrame>}

function Reset(){const loc=useLocation(),token=new URLSearchParams(loc.search).get('token')||'',[f,setF]=useState({password:'',confirmPassword:''}),[error,setError]=useState(''),[done,setDone]=useState(''),[busy,setBusy]=useState(false);const go=async e=>{e.preventDefault();setError('');if(!PW_RULE.test(f.password))return setError('Password must be 8–20 characters with an upper-case letter, a lower-case letter, a digit and a special character.');if(f.password!==f.confirmPassword)return setError('The passwords entered do not match.');setBusy(true);try{const x=await api.post('/auth/reset-password',{token,...f});setDone(x.message)}catch(x){setError(x.message)}finally{setBusy(false)}};return <AuthFrame><form className="auth-card" onSubmit={go}><span className="eyebrow">ACCOUNT RECOVERY</span><h2>Choose a new password</h2>{!token&&<div className="alert error">This reset link is incomplete. Request a new one.</div>}{error&&<div className="alert error">{error}</div>}{done?<div className="alert success">{done}</div>:<><label>New password<input type="password" value={f.password} onChange={e=>setF({...f,password:e.target.value})} required/></label><label>Confirm new password<input type="password" value={f.confirmPassword} onChange={e=>setF({...f,confirmPassword:e.target.value})} required/></label><button className="btn primary full" disabled={busy||!token}>{busy?'Please wait…':'Reset password'}</button></>}<p className="muted center"><Link to="/" className="small-link">Back to sign in</Link></p></form></AuthFrame>}

function Root(){return <AuthProvider><App/></AuthProvider>}createRoot(document.getElementById('root')).render(<BrowserRouter><Root/></BrowserRouter>);
